        var design=await flow.Admin.PostAsJsonAsync($"/api/v1/admin/interior/projects/{flow.Project.Id}/designs",new{title="주방 설계안",description="동선 중심 1차 설계",fileIds=Array.Empty<Guid>(),idempotencyKey=$"design-{Guid.NewGuid():N}"});Assert.Equal(HttpStatusCode.OK,design.StatusCode);await SelectProvider(flow.Customer,flow.Project.Id,revision);
        var contractResponse=await flow.Admin.PostAsJsonAsync($"/api/v1/admin/interior/projects/{flow.Project.Id}/contracts",new{providerId,quoteRevisionId=revision,contractAmount=12000000m,currencyCode="KRW",scopeSnapshotJson="{\"scope\":\"주방 리모델링\"}",scheduleSnapshotJson="{\"days\":20}",warrantySnapshotJson="{\"days\":30}",plannedStartDate=DateOnly.FromDateTime(DateTime.Today.AddDays(3)),plannedCompletionDate=DateOnly.FromDateTime(DateTime.Today.AddDays(23)),paymentPlans=new[]{new{sequenceNo=1,name="계약 지급",amount=3000000m,dueDate=(DateOnly?)null,condition="양 당사자 동의 후"}},idempotencyKey=$"contract-{Guid.NewGuid():N}"});var contract=(await contractResponse.Content.ReadFromJsonAsync<InteriorContractResponse>())!;
        Assert.Equal(HttpStatusCode.OK,(await flow.Customer.PostAsJsonAsync($"/api/v1/customers/me/interior/projects/{flow.Project.Id}/contracts/{contract.Id}/agreement",new{idempotencyKey=$"agree-c-{Guid.NewGuid():N}"})).StatusCode);Assert.Equal(HttpStatusCode.OK,(await provider.PostAsJsonAsync($"/api/v1/interior/contracts/{contract.Id}/agreement",new{idempotencyKey=$"agree-p-{Guid.NewGuid():N}",rowVersion=(string?)null})).StatusCode);
        var detail=await flow.Customer.GetFromJsonAsync<CustomerInteriorProjectDetail>($"/api/v1/customers/me/interior/projects/{flow.Project.Id}");Assert.Contains(detail!.Quotes,x=>x.PurposeCode=="POST_SITE_VISIT"&&x.Items.Count==2);Assert.Single(detail.Designs);Assert.Equal("EFFECTIVE",detail.Contract!.StatusCode);Assert.Single(detail.Contract.Versions);var plan=Assert.Single(detail.Contract.PaymentPlans);
        Assert.Equal(HttpStatusCode.OK,(await flow.Customer.PostAsJsonAsync($"/api/v1/customers/me/interior/projects/{flow.Project.Id}/payment-plans/{plan.Id}/confirmations",new{confirmationTypeCode="CUSTOMER_DIRECT_PAYMENT",amount=3000000m,confirmedAt=DateTime.UtcNow,evidenceFileId=(Guid?)null,note="공급자에게 직접 지급",idempotencyKey=$"pay-{Guid.NewGuid():N}"})).StatusCode);
        var stageResponse=await flow.Admin.PostAsJsonAsync($"/api/v1/admin/interior/projects/{flow.Project.Id}/stages",new{sequenceNo=1,name="철거",plannedStartDate=DateOnly.FromDateTime(DateTime.Today.AddDays(3)),plannedEndDate=DateOnly.FromDateTime(DateTime.Today.AddDays(6)),idempotencyKey=$"stage-{Guid.NewGuid():N}"});var stage=(await stageResponse.Content.ReadFromJsonAsync<InteriorWorkStageResponse>())!;
        await provider.PostAsJsonAsync($"/api/v1/interior/stages/{stage.Id}/updates",new{progressPercent=60,updateText="철거 진행",issueText="폐기물 반출 일정 확인",fileIds=Array.Empty<Guid>(),idempotencyKey=$"update-{Guid.NewGuid():N}",rowVersion=(string?)null});await flow.Admin.PostAsJsonAsync($"/api/v1/admin/interior/stages/{stage.Id}/inspections",new{inspectionStatusCode="CORRECTION_REQUIRED",checklistJson="{\"clean\":false}",resultText="보완 필요",requestedCorrectionText="잔재물 정리",idempotencyKey=$"inspect-{Guid.NewGuid():N}"});
        var changeResponse=await provider.PostAsJsonAsync($"/api/v1/interior/contracts/{contract.Id}/changes",new{changeTypeCode="ADDITIONAL_WORK",reason="고객 요청",scopeChange="수납장 추가",amountDelta=500000m,scheduleImpactDays=2,idempotencyKey=$"change-{Guid.NewGuid():N}"});var change=(await changeResponse.Content.ReadFromJsonAsync<InteriorChangeResponse>())!;
        using(var scope=factory.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<SoodalLifeDbContext>();Assert.Equal(12000000m,(await db.InteriorContracts.SingleAsync(x=>x.PublicId==contract.Id)).ContractAmount);}Assert.Equal(HttpStatusCode.OK,(await flow.Customer.PostAsJsonAsync($"/api/v1/customers/me/interior/projects/{flow.Project.Id}/changes/{change.Id}/decision",new{approve=true,idempotencyKey=$"decide-{Guid.NewGuid():N}"})).StatusCode);
        Assert.Equal(HttpStatusCode.OK,(await provider.PostAsJsonAsync($"/api/v1/interior/stages/{stage.Id}/updates",new{progressPercent=100,updateText="철거 및 정리 완료",issueText=(string?)null,fileIds=Array.Empty<Guid>(),idempotencyKey=$"update-final-{Guid.NewGuid():N}",rowVersion=(string?)null})).StatusCode);Assert.Equal(HttpStatusCode.OK,(await provider.PostAsJsonAsync($"/api/v1/interior/projects/{flow.Project.Id}/completion-report",new{completionSummary="승인 범위 완료",finalChecklistJson="{\"handover\":true}",idempotencyKey=$"provider-complete-{Guid.NewGuid():N}",rowVersion=(string?)null})).StatusCode);var passedInspection=await flow.Admin.PostAsJsonAsync($"/api/v1/admin/interior/stages/{stage.Id}/inspections",new{inspectionStatusCode="PASSED",checklistJson="{\"clean\":true}",resultText="최종 검사 통과",requestedCorrectionText=(string?)null,idempotencyKey=$"inspect-final-{Guid.NewGuid():N}"});Assert.Equal(HttpStatusCode.OK,passedInspection.StatusCode);var passedInspectionId=await passedInspection.Content.ReadFromJsonAsync<Guid>();Assert.Equal(HttpStatusCode.OK,(await flow.Customer.PostAsJsonAsync($"/api/v1/customers/me/interior/projects/{flow.Project.Id}/inspections/{passedInspectionId}/acknowledgement",new{comment="검사 결과 확인",idempotencyKey=$"inspect-ack-{Guid.NewGuid():N}",rowVersion=(string?)null})).StatusCode);Assert.Equal(HttpStatusCode.OK,(await flow.Customer.PostAsJsonAsync($"/api/v1/customers/me/interior/projects/{flow.Project.Id}/completion-acknowledgement",new{comment="완료 확인",idempotencyKey=$"completion-ack-{Guid.NewGuid():N}",rowVersion=(string?)null})).StatusCode);Assert.Equal(HttpStatusCode.OK,(await flow.Admin.PostAsJsonAsync($"/api/v1/admin/interior/projects/{flow.Project.Id}/completion",new{finalChecklistJson="{\"handover\":true}",completionSummary="승인 범위 완료",idempotencyKey=$"complete-{Guid.NewGuid():N}",rowVersion=(string?)null})).StatusCode);detail=await flow.Customer.GetFromJsonAsync<CustomerInteriorProjectDetail>($"/api/v1/customers/me/interior/projects/{flow.Project.Id}");Assert.Equal(12500000m,detail!.Contract!.Amount);Assert.Equal(2,detail.Contract.Versions.Count);Assert.Equal(100,Assert.Single(detail.WorkStages).ProgressPercent);Assert.Contains(Assert.Single(detail.WorkStages).Inspections,x=>x.StatusCode=="CORRECTION_REQUIRED");Assert.Contains(Assert.Single(detail.WorkStages).Inspections,x=>x.StatusCode=="PASSED"&&x.AcknowledgedAt.HasValue);Assert.NotNull(detail.Completion);
    }

    [Fact]
    public async Task InteriorDefectAndDispute_ReuseCommonWorkflows_WithoutWalletFeeTrustOrSubscriptionMutation()
    {
        var flow=await CreateProject();var providerId=await ProviderId(factory.Credentials[RoleCodes.Provider]);var revision=await SeedQuote(flow.RequestId,providerId);await SelectProvider(flow.Customer,flow.Project.Id,revision);var contractResponse=await flow.Admin.PostAsJsonAsync($"/api/v1/admin/interior/projects/{flow.Project.Id}/contracts",new{providerId,quoteRevisionId=revision,contractAmount=12000000m,currencyCode="KRW",scopeSnapshotJson="{}",scheduleSnapshotJson="{}",warrantySnapshotJson="{\"days\":30}",plannedStartDate=DateOnly.FromDateTime(DateTime.Today),plannedCompletionDate=DateOnly.FromDateTime(DateTime.Today.AddDays(1)),paymentPlans=Array.Empty<object>(),idempotencyKey=$"contract-{Guid.NewGuid():N}"});Assert.Equal(HttpStatusCode.OK,contractResponse.StatusCode);await flow.Admin.PostAsJsonAsync($"/api/v1/admin/interior/projects/{flow.Project.Id}/completion",new{finalChecklistJson="{}",completionSummary="완료",idempotencyKey=$"complete-{Guid.NewGuid():N}",rowVersion=(string?)null});
        int wallets,ledger,fees,trustEvents,subscriptions;decimal? trust;using(var scope=factory.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<SoodalLifeDbContext>();wallets=await db.ProviderWallets.CountAsync();ledger=await db.WalletLedgerEntries.CountAsync();fees=await db.FeeCharges.CountAsync();trustEvents=await db.TrustScoreEvents.CountAsync();subscriptions=await db.SubscriptionContracts.CountAsync();var provider=await db.ProviderProfiles.SingleAsync(x=>x.PublicId==providerId);trust=await db.ProviderTrustScoreCurrent.Where(x=>x.ProviderProfileId==provider.Id).Select(x=>(decimal?)x.Score).SingleOrDefaultAsync();}
        var defect=await flow.Customer.PostAsJsonAsync($"/api/v1/customers/me/interior/projects/{flow.Project.Id}/defects",new{workStageId=(Guid?)null,contractVersion=1,location="주방 벽면",subject="도장 들뜸",description="완료 후 도장 들뜸이 확인됩니다.",fileIds=Array.Empty<Guid>(),idempotencyKey=$"defect-{Guid.NewGuid():N}"});Assert.Equal(HttpStatusCode.OK,defect.StatusCode);var defectDetail=await defect.Content.ReadFromJsonAsync<CustomerInteriorProjectDetail>();var dispute=await flow.Customer.PostAsJsonAsync($"/api/v1/customers/me/after-services/{defectDetail!.Defects[0].AfterServiceCaseId}/dispute",new{subject="보완 범위 확인",reason="보완 범위에 대한 중재가 필요합니다.",requestedResolution="보완 범위를 확인해 주세요.",idempotencyKey=$"dispute-{Guid.NewGuid():N}"});Assert.Equal(HttpStatusCode.OK,dispute.StatusCode);
        var detailResponse=await flow.Customer.GetAsync($"/api/v1/customers/me/interior/projects/{flow.Project.Id}");var detail=await detailResponse.Content.ReadFromJsonAsync<CustomerInteriorProjectDetail>();Assert.Single(detail!.Defects);Assert.Single(detail.Disputes);Assert.Equal(HttpStatusCode.OK,(await flow.Customer.GetAsync($"/api/v1/after-services/{detail.Defects[0].AfterServiceCaseId}")).StatusCode);Assert.Equal(HttpStatusCode.OK,(await flow.Customer.GetAsync($"/api/v1/customers/me/disputes/{detail.Disputes[0].Id}")).StatusCode);using var verifyScope=factory.Services.CreateScope();var verify=verifyScope.ServiceProvider.GetRequiredService<SoodalLifeDbContext>();var project=await verify.InteriorProjects.SingleAsync(x=>x.PublicId==flow.Project.Id);Assert.Single(await verify.AfterServiceCases.Where(x=>x.InteriorProjectId==project.Id).ToListAsync());Assert.Single(await verify.InteriorDefects.Where(x=>x.InteriorProjectId==project.Id).ToListAsync());Assert.Single(await verify.DisputeCases.Where(x=>x.InteriorProjectId==project.Id).ToListAsync());Assert.Equal(wallets,await verify.ProviderWallets.CountAsync());Assert.Equal(ledger,await verify.WalletLedgerEntries.CountAsync());Assert.Equal(fees,await verify.FeeCharges.CountAsync());Assert.Equal(trustEvents,await verify.TrustScoreEvents.CountAsync());Assert.Equal(subscriptions,await verify.SubscriptionContracts.CountAsync());var verifiedProvider=await verify.ProviderProfiles.SingleAsync(x=>x.PublicId==providerId);Assert.Equal(trust,await verify.ProviderTrustScoreCurrent.Where(x=>x.ProviderProfileId==verifiedProvider.Id).Select(x=>(decimal?)x.Score).SingleOrDefaultAsync());Assert.Equal("POLICY_PENDING",project.FeeAssessmentStatusCode);
        using var admin=Client();await Login(admin,factory.Credentials[RoleCodes.Admin]);Assert.Equal(HttpStatusCode.OK,(await admin.GetAsync("/api/v1/admin/interior/projects")).StatusCode);Assert.Equal(HttpStatusCode.OK,(await admin.GetAsync("/api/v1/admin/after-services")).StatusCode);
    }

    [Fact]
    public async Task Customer_SelectsOneLatestInteriorProvider_WithoutCreatingContractOrFee()
    {
        var flow=await CreateProject();var providerId=await ProviderId(factory.Credentials[RoleCodes.Provider]);var revision=await SeedQuote(flow.RequestId,providerId);using var provider=Client();using var otherProvider=Client();await Login(provider,factory.Credentials[RoleCodes.Provider]);await Login(otherProvider,factory.AreaMismatchProviderCredential);
        int wallets,ledger,fees,trustEvents;using(var scope=factory.Services.CreateScope()){var before=scope.ServiceProvider.GetRequiredService<SoodalLifeDbContext>();wallets=await before.ProviderWallets.CountAsync();ledger=await before.WalletLedgerEntries.CountAsync();fees=await before.FeeCharges.CountAsync();trustEvents=await before.TrustScoreEvents.CountAsync();}
        var beforeSelection=await flow.Customer.GetFromJsonAsync<CustomerInteriorProjectDetail>($"/api/v1/customers/me/interior/projects/{flow.Project.Id}");var quote=Assert.Single(beforeSelection!.Quotes);Assert.True(quote.CanSelect);Assert.Equal(revision,quote.RevisionId);Assert.Equal(providerId,quote.ProviderId);
        var premature=await flow.Admin.PostAsJsonAsync($"/api/v1/admin/interior/projects/{flow.Project.Id}/contracts",new{providerId,quoteRevisionId=revision,contractAmount=12000000m,currencyCode="KRW",scopeSnapshotJson="{}",scheduleSnapshotJson="{}",warrantySnapshotJson="{}",plannedStartDate=DateOnly.FromDateTime(DateTime.Today),plannedCompletionDate=DateOnly.FromDateTime(DateTime.Today.AddDays(1)),paymentPlans=Array.Empty<object>(),idempotencyKey=$"premature-{Guid.NewGuid():N}"});Assert.Equal(HttpStatusCode.Conflict,premature.StatusCode);
        var key=$"select-provider-{Guid.NewGuid():N}";var response=await flow.Customer.PostAsJsonAsync($"/api/v1/customers/me/interior/projects/{flow.Project.Id}/provider-selection",new{quoteRevisionId=revision,rowVersion=beforeSelection.RowVersion,idempotencyKey=key});Assert.Equal(HttpStatusCode.OK,response.StatusCode);var selected=(await response.Content.ReadFromJsonAsync<CustomerInteriorProjectDetail>())!;Assert.Equal(providerId,selected.ProviderSelection!.ProviderId);Assert.Equal(revision,selected.ProviderSelection.QuoteRevisionId);Assert.Null(selected.Contract);Assert.True(Assert.Single(selected.Quotes).Selected);Assert.False(Assert.Single(selected.Quotes).CanSelect);
        Assert.Equal(HttpStatusCode.OK,(await flow.Customer.PostAsJsonAsync($"/api/v1/customers/me/interior/projects/{flow.Project.Id}/provider-selection",new{quoteRevisionId=revision,rowVersion=beforeSelection.RowVersion,idempotencyKey=key})).StatusCode);Assert.Equal(HttpStatusCode.OK,(await provider.GetAsync($"/api/v1/providers/me/interior/projects/{flow.Project.Id}")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await otherProvider.GetAsync($"/api/v1/providers/me/interior/projects/{flow.Project.Id}")).StatusCode);Assert.Equal(HttpStatusCode.OK,(await flow.Customer.GetAsync($"/api/v1/chat/interiors/{flow.Project.Id}/room?role=PRIMARY_CONTRACTOR")).StatusCode);Assert.Equal(HttpStatusCode.OK,(await provider.GetAsync($"/api/v1/chat/interiors/{flow.Project.Id}/room?role=PRIMARY_CONTRACTOR")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await otherProvider.GetAsync($"/api/v1/chat/interiors/{flow.Project.Id}/room?role=PRIMARY_CONTRACTOR")).StatusCode);
        using var verifyScope=factory.Services.CreateScope();var verify=verifyScope.ServiceProvider.GetRequiredService<SoodalLifeDbContext>();var project=await verify.InteriorProjects.SingleAsync(x=>x.PublicId==flow.Project.Id);Assert.Equal("POLICY_PENDING",project.FeeAssessmentStatusCode);Assert.Null(project.CurrentContractId);Assert.Single(await verify.InteriorProjectParticipants.Where(x=>x.InteriorProjectId==project.Id&&x.RoleCode=="PRIMARY_CONTRACTOR"&&x.StatusCode=="ACTIVE").ToListAsync());Assert.Single(await verify.InteriorProjectEvents.Where(x=>x.InteriorProjectId==project.Id&&x.EventTypeCode=="CONTRACTOR_SELECTED").ToListAsync());Assert.Equal(wallets,await verify.ProviderWallets.CountAsync());Assert.Equal(ledger,await verify.WalletLedgerEntries.CountAsync());Assert.Equal(fees,await verify.FeeCharges.CountAsync());Assert.Equal(trustEvents,await verify.TrustScoreEvents.CountAsync());
    }

    [Fact]
    public async Task ProviderSelection_RejectsOtherActorsOldRevisionAndWithdrawnQuote()
    {
        var flow=await CreateProject();var providerId=await ProviderId(factory.Credentials[RoleCodes.Provider]);var revision=await SeedQuote(flow.RequestId,providerId);using var other=Client();using var provider=Client();await Login(other,factory.OtherCustomerCredential);await Login(provider,factory.Credentials[RoleCodes.Provider]);var detail=await flow.Customer.GetFromJsonAsync<CustomerInteriorProjectDetail>($"/api/v1/customers/me/interior/projects/{flow.Project.Id}");var body=new{quoteRevisionId=revision,rowVersion=detail!.RowVersion,idempotencyKey=$"select-provider-{Guid.NewGuid():N}"};Assert.Equal(HttpStatusCode.NotFound,(await other.PostAsJsonAsync($"/api/v1/customers/me/interior/projects/{flow.Project.Id}/provider-selection",body)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await provider.PostAsJsonAsync($"/api/v1/customers/me/interior/projects/{flow.Project.Id}/provider-selection",body)).StatusCode);
        using(var scope=factory.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<SoodalLifeDbContext>();var first=await db.QuoteRevisions.SingleAsync(x=>x.PublicId==revision);db.QuoteRevisions.Add(new(){QuoteId=first.QuoteId,RevisionNo=2,RevisionPurposeCode="POST_SITE_VISIT",Summary="최신 상세견적",SubtotalAmount=first.SubtotalAmount,VatAmount=first.VatAmount,TotalAmount=first.TotalAmount,CurrencyCode=first.CurrencyCode,ValidUntil=DateTime.UtcNow.AddDays(7),SubmittedAt=DateTime.UtcNow,SubmittedByUserId=first.SubmittedByUserId,IdempotencyKey=$"quote-{Guid.NewGuid():N}"});await db.SaveChangesAsync();}
        Assert.Equal(HttpStatusCode.Conflict,(await flow.Customer.PostAsJsonAsync($"/api/v1/customers/me/interior/projects/{flow.Project.Id}/provider-selection",new{quoteRevisionId=revision,rowVersion=detail.RowVersion,idempotencyKey=$"old-{Guid.NewGuid():N}"})).StatusCode);using(var scope=factory.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<SoodalLifeDbContext>();var requestId=await db.ServiceRequests.Where(x=>x.PublicId==flow.RequestId).Select(x=>x.Id).SingleAsync();var quote=await db.Quotes.SingleAsync(x=>x.ServiceRequestId==requestId);quote.WithdrawnAt=DateTime.UtcNow;await db.SaveChangesAsync();}Assert.Empty((await flow.Customer.GetFromJsonAsync<CustomerInteriorProjectDetail>($"/api/v1/customers/me/interior/projects/{flow.Project.Id}"))!.Quotes);
    }

    [Fact]
    public async Task ProviderSelection_BlocksSecondSelectionAndAdminReadsSnapshot()
    {
        var flow=await CreateProject();var providerId=await ProviderId(factory.Credentials[RoleCodes.Provider]);var revision=await SeedQuote(flow.RequestId,providerId);await SelectProvider(flow.Customer,flow.Project.Id,revision);var detail=await flow.Customer.GetFromJsonAsync<CustomerInteriorProjectDetail>($"/api/v1/customers/me/interior/projects/{flow.Project.Id}");Assert.Equal(HttpStatusCode.Conflict,(await flow.Customer.PostAsJsonAsync($"/api/v1/customers/me/interior/projects/{flow.Project.Id}/provider-selection",new{quoteRevisionId=revision,rowVersion=detail!.RowVersion,idempotencyKey=$"second-{Guid.NewGuid():N}"})).StatusCode);var admin=await flow.Admin.GetFromJsonAsync<InteriorProjectDetail>($"/api/v1/admin/interior/projects/{flow.Project.Id}");Assert.Equal(revision,admin!.SelectedQuoteRevisionId);Assert.Equal(1,admin.SelectedQuoteRevisionNo);Assert.NotNull(admin.ContractorSelectedAt);Assert.Empty(admin.Contracts);
