    }

    private async Task<Flow> CreateProject(){var request=await SeedRequest();var customer=Client();var admin=Client();await Login(customer,factory.Credentials[RoleCodes.Customer]);await Login(admin,factory.Credentials[RoleCodes.Admin]);var response=await customer.PostAsJsonAsync("/api/v1/customers/me/interior/projects",new{serviceRequestId=request,idempotencyKey=$"create-{Guid.NewGuid():N}"});Assert.Equal(HttpStatusCode.OK,response.StatusCode);return new(customer,admin,(await response.Content.ReadFromJsonAsync<CustomerInteriorProjectDetail>())!,request);}
    private async Task<Guid> SeedRequest(){using var scope=factory.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<SoodalLifeDbContext>();var service=await db.ServiceCategories.SingleAsync(x=>x.PublicId==factory.Catalog.ServiceId);service.ExternalCode="INT-TEST";var middle=await db.ServiceCategories.SingleAsync(x=>x.Id==service.ParentId);var major=await db.ServiceCategories.SingleAsync(x=>x.Id==middle.ParentId);major.Name="인테리어";var customer=await(from user in db.Users join profile in db.CustomerProfiles on user.Id equals profile.UserId where user.LoginId==factory.Credentials[RoleCodes.Customer].LoginId select new{user,profile}).SingleAsync();customer.user.Phone="010-2468-1357";var policy=await db.CategoryPolicies.FirstAsync(x=>x.CategoryId==service.Id);var area=await db.AdministrativeAreas.SingleAsync(x=>x.PublicId==factory.Catalog.AreaId);var now=DateTime.UtcNow;var request=new ServiceRequest{CustomerProfileId=customer.profile.Id,CategoryId=service.Id,CategoryPolicyId=policy.Id,AdministrativeAreaId=area.Id,DetailAddress="101동 1203호",Title=$"인테리어 상담 {Guid.NewGuid():N}",Description="주방과 거실 공사를 요청합니다.",StatusCode="OPEN",PolicySnapshotJson="{}",OpenedAt=now,CreatedAt=now,CreatedByUserId=customer.user.Id,UpdatedAt=now,UpdatedByUserId=customer.user.Id};db.ServiceRequests.Add(request);await db.SaveChangesAsync();return request.PublicId;}
    private async Task<Guid> SeedQuote(Guid requestId,Guid providerId){using var scope=factory.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<SoodalLifeDbContext>();var request=await db.ServiceRequests.SingleAsync(x=>x.PublicId==requestId);var project=await db.InteriorProjects.SingleAsync(x=>x.ServiceRequestId==request.Id);project.StatusCode="ESTIMATE_READY";var provider=await db.ProviderProfiles.SingleAsync(x=>x.PublicId==providerId);var now=DateTime.UtcNow;var quote=new Quote{ServiceRequestId=request.Id,ProviderProfileId=provider.Id,RequestDispatchId=0,StatusCode="SUBMITTED",SubmittedAt=now,ExpiresAt=now.AddDays(7),CreatedAt=now,UpdatedAt=now};db.Quotes.Add(quote);await db.SaveChangesAsync();var revision=new QuoteRevision{QuoteId=quote.Id,RevisionNo=1,RevisionPurposeCode="POST_SITE_VISIT",Summary="실측 후 상세견적",Terms="철거와 폐기 포함",SubtotalAmount=10909091m,VatAmount=1090909m,TotalAmount=12000000m,CurrencyCode="KRW",EstimatedDurationText="20일",ValidUntil=now.AddDays(7),SubmittedAt=now,SubmittedByUserId=provider.UserId,IdempotencyKey=$"quote-{Guid.NewGuid():N}"};db.QuoteRevisions.Add(revision);await db.SaveChangesAsync();db.QuoteItems.AddRange(new QuoteItem{QuoteRevisionId=revision.Id,LineNo=1,ItemName="철거",Quantity=1,UnitText="식",UnitPriceAmount=2000000,LineTotalAmount=2000000,CurrencyCode="KRW",WorkTradeText="철거",SpaceText="주방",LaborNoteText="폐기물 포함"},new QuoteItem{QuoteRevisionId=revision.Id,LineNo=2,ItemName="수납장",Quantity=1,UnitText="식",UnitPriceAmount=10000000,LineTotalAmount=10000000,CurrencyCode="KRW",WorkTradeText="목공",SpaceText="주방",MaterialSpecText="친환경 자재"});await db.SaveChangesAsync();return revision.PublicId;}
    private async Task SelectProvider(HttpClient customer,Guid projectId,Guid quoteRevisionId){var detail=await customer.GetFromJsonAsync<CustomerInteriorProjectDetail>($"/api/v1/customers/me/interior/projects/{projectId}");var response=await customer.PostAsJsonAsync($"/api/v1/customers/me/interior/projects/{projectId}/provider-selection",new{quoteRevisionId,rowVersion=detail!.RowVersion,idempotencyKey=$"select-provider-{Guid.NewGuid():N}"});Assert.Equal(HttpStatusCode.OK,response.StatusCode);}
    private async Task<Guid> ProviderId(TestCredential credential){using var scope=factory.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<SoodalLifeDbContext>();return await(from user in db.Users join provider in db.ProviderProfiles on user.Id equals provider.UserId where user.LoginId==credential.LoginId select provider.PublicId).SingleAsync();}
    private HttpClient Client()=>factory.CreateClient(new WebApplicationFactoryClientOptions{AllowAutoRedirect=false,HandleCookies=true});private static async Task Login(HttpClient client,TestCredential value)=>Assert.Equal(HttpStatusCode.OK,(await client.PostAsJsonAsync("/api/v1/auth/login",new{LoginOrEmail=value.LoginId,value.Password})).StatusCode);
    private sealed record Flow(HttpClient Customer,HttpClient Admin,CustomerInteriorProjectDetail Project,Guid RequestId);
}
